from melite_models import Model, Variant, Cell, LoraRow, SourceRow, Genre, Quant


class GemSoma(Model):
    id = 'gem_soma'
    engine = 'comfyui'
    genre = Genre.OTHER
    label = 'SOMA'
    description = 'GEM-X SOMA pose estimation and retargeting.'
    form = 'form_edit'
    # card: NONE — a tool lane, not a family head of image-edit
    # (unboarded 2026-09-04: no edit weights; returns when its own
    # nodeset/card exists — the ControlNetMod law)
    source = SourceRow(repo_id='nvidia/soma-x')
    defaults = dict(
            scheduler='simple',
            width=1024,
            height=1024,
            steps=25,
            sampler='euler',
            cfg=7.0,
        )

    # the CASCADE GATE (image-edit rework 2026-09-05) — a weightless
    # tool / transport / preprocessor lane ships NATIVE as its single
    # quant (no weights matrix; the lane's own engine owns whatever
    # load it has).
    variants = (
        Variant(id='standard', label='Standard', route='gem_soma', cells=(
            Cell(quant=Quant.NATIVE, label='Native (weightless)', route='gem_soma'),
        )),
    )

